keyframes:
@keyframes custom-agents-status-start { 
  0% { opacity: 0; top: 0px; }
  15%, 85% { opacity: 1; top: -28px; }
  100% { opacity: 0; top: 0px; }
}

@keyframes custom-agents-completed-exit { 
  0% { opacity: 1; transform: translateY(0px); }
  100% { opacity: 0; transform: translateY(28px); }
}

@keyframes shelf-hero-for-mcp-module__lRYFwa__logo-in { 
  0% { opacity: 0; filter: blur(3px); }
  100% { opacity: 1; filter: blur(); }
}

@keyframes running { 
  0% { opacity: 0; top: 0px; }
  15%, 85% { opacity: 1; top: -28px; }
  100% { opacity: 0; top: 0px; }
}

@keyframes reporting-radar-ring-pulse { 
  0% { border-color: var(--color-subtle-stroke); }
  7% { border-color: color-mix(in oklab, var(--color-blue-500) 32%, var(--color-subtle-stroke)); }
  26%, 100% { border-color: var(--color-subtle-stroke); }
}

@keyframes reporting-radar-dot { 
  0% { opacity: 0; scale: 0.4; }
  3% { opacity: 1; scale: 2.2; }
  9%, 92% { opacity: 1; scale: 1; }
  100% { opacity: 0; scale: 1; }
}

@keyframes reporting-radar-enter { 
  0% { opacity: 0; translate: 0px 8px; scale: 0.96; }
  100% { opacity: 1; translate: 0px; scale: 1; }
}

@keyframes reporting-card-role { 
  0% { --reporting-reveal: 1; --reporting-dim: 0; z-index: 2; visibility: visible; }
  25% { --reporting-reveal: 0; --reporting-dim: 1; z-index: 1; visibility: visible; }
  50%, 100% { --reporting-reveal: 0; --reporting-dim: 0; z-index: 0; visibility: hidden; }
}

@keyframes universal-context-horizon-define { 
  0% { opacity: 1; transform: scale(1); }
  65% { opacity: 1; }
  100% { opacity: 0; transform: scale(0.8); }
}

@keyframes enter { 
  0% { opacity: var(--tw-enter-opacity,1); transform: translate3d(var(--tw-enter-translate-x,0), var(--tw-enter-translate-y,0), var(--tw-enter-translate-z,0)) scale3d(var(--tw-enter-scale,1), var(--tw-enter-scale,1), var(--tw-enter-scale,1)) rotateX(var(--tw-enter-rotate-x,0)) rotateY(var(--tw-enter-rotate-y,0)) rotate(var(--tw-enter-rotate,0)); }
}

@keyframes exit { 
  100% { opacity: var(--tw-exit-opacity,1); transform: translate3d(var(--tw-exit-translate-x,0), var(--tw-exit-translate-y,0), var(--tw-exit-translate-z,0)) scale3d(var(--tw-exit-scale,1), var(--tw-exit-scale,1), var(--tw-exit-scale,1)) rotateX(var(--tw-exit-rotate-x,0)) rotateY(var(--tw-exit-rotate-y,0)) rotate(var(--tw-exit-rotate,0)); }
}

@keyframes navigation-enter-from-right { 
  0% { opacity: 0; filter: blur(8px); transform: translate(200px); }
  100% { opacity: 1; filter: blur(); transform: translate(0px); }
}

@keyframes navigation-enter-from-left { 
  0% { opacity: 0; filter: blur(8px); transform: translate(-200px); }
  100% { opacity: 1; filter: blur(); transform: translate(0px); }
}

@keyframes navigation-exit-to-right { 
  0% { opacity: 1; filter: blur(); transform: translate(0px); }
  100% { opacity: 0; filter: blur(8px); transform: translate(200px); }
}

@keyframes navigation-exit-to-left { 
  0% { opacity: 1; filter: blur(); transform: translate(0px); }
  100% { opacity: 0; filter: blur(8px); transform: translate(-200px); }
}

@keyframes productivity-intro-height { 
  0% { opacity: 0.8; height: 0px; }
  100% { height: var(--productivity-intro-height-to); opacity: 0.3; }
}
